import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"4. Solution Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/arc42/04-solution-strategy.md","filePath":"architecture/arc42/04-solution-strategy.md","lastUpdated":1780254295000}'),i={name:"architecture/arc42/04-solution-strategy.md"};function s(l,e,n,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="_4-solution-strategy" tabindex="-1">4. Solution Strategy <a class="header-anchor" href="#_4-solution-strategy" aria-label="Permalink to &quot;4. Solution Strategy&quot;">​</a></h1><h2 id="in-process-daemon-thin-uis" tabindex="-1">In-process daemon + thin UIs <a class="header-anchor" href="#in-process-daemon-thin-uis" aria-label="Permalink to &quot;In-process daemon + thin UIs&quot;">​</a></h2><ul><li>Desktop apps are UI-first and delegate networking/storage/security to the <code>soma-daemon</code> library, which the Electron main process loads in-process via the <code>@soma/node</code> napi addon (see ADR-0001 for the history).</li><li>The daemon exposes no IPC socket and no TCP service on user devices; the only inter-process boundary on the desktop side is the renderer ↔ main Electron IPC bridge.</li></ul><h2 id="libp2p-for-decentralized-networking" tabindex="-1">libp2p for decentralized networking <a class="header-anchor" href="#libp2p-for-decentralized-networking" aria-label="Permalink to &quot;libp2p for decentralized networking&quot;">​</a></h2><ul><li>Each desktop daemon and each <code>somad bot</code> is a libp2p peer with a stable PeerId derived from its keypair.</li><li>Discovery and connectivity use a layered approach: direct addresses, mDNS (LAN), rendezvous (internet discovery), relay fallback.</li></ul><h2 id="capability-based-membership" tabindex="-1">Capability-based membership <a class="header-anchor" href="#capability-based-membership" aria-label="Permalink to &quot;Capability-based membership&quot;">​</a></h2><ul><li>Membership is explicit and cryptographically verifiable (see ADR-0002).</li><li>Bots may be delegated join authority via issuer capabilities; otherwise joins are manual.</li></ul><h2 id="cache-only-peers-vdfs" tabindex="-1">Cache-only peers (VDFs) <a class="header-anchor" href="#cache-only-peers-vdfs" aria-label="Permalink to &quot;Cache-only peers (VDFs)&quot;">​</a></h2><ul><li><code>somad bot</code> is a cache-only peer role intended to improve availability/latency (see ADR-0003).</li><li>VDFs never accept user uploads; they fill caches only via fetch-by-CID with CID verification.</li></ul><h2 id="content-addressed-blobs" tabindex="-1">Content-addressed blobs <a class="header-anchor" href="#content-addressed-blobs" aria-label="Permalink to &quot;Content-addressed blobs&quot;">​</a></h2><ul><li>Large binary assets live outside collaborative state and are addressed by CID (SHA-256 hex today).</li><li>Blob transfer is pull-based by CID over <code>/soma/blob/1</code> and is size-bounded (see blob docs and ADR-0004).</li></ul><h2 id="controller-service-separation" tabindex="-1">Controller/service separation <a class="header-anchor" href="#controller-service-separation" aria-label="Permalink to &quot;Controller/service separation&quot;">​</a></h2><ul><li>Axum surfaces (on the server side) are controllers; peer runtime and repositories hold business logic.</li><li>Peer events are routed through a dispatcher with bounded queues to avoid blocking the network loop.</li></ul>',13)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
